WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY txn_time DESC, id) AS rank_in_group FROM transactions QUALIFY rank_in_group = 1) SELECT CASE WHEN amount >= 3000 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN txn_type = 'FEE' THEN 1 END), 0), 2) AS amount_per_fee, COUNT_IF(merchant = 'Shell') AS shell_events, MIN(amount) AS min_amount, MIN(amount) AS min_amount_2, COUNT(DISTINCT id) AS distinct_ids, SUM(CASE WHEN merchant = 'Lazada' THEN amount ELSE 0 END) AS lazada_amount FROM latest GROUP BY CASE WHEN amount >= 3000 THEN 'LARGE' ELSE 'SMALL' END ORDER BY shell_events DESC NULLS LAST
